 {Bytes ram=ff_node();put(ram,NODE+0xa7,1,0xfb);State s=st(0x1dc92);
  check(runs_to(ram,s,0x1aa3a)&&get(ram,NODE+0xa7,1)==0xffU&&get(ram,NODE+0x68,2)==0x8834U&&get(ram,NODE+0x1e,2)==0x8834U&&get(ram,NODE,4)==0x1f3e0U&&
   get(ram,NODE+0x67,1)==0xffU&&get(ram,NODE+0x6a,1)==0xffU&&get(ram,NODE+0x1d,1)==0xffU&&get(ram,NODE+0x20,1)==0xffU&&get(ram,NODE+4,1)==0xffU&&
   get(ram,SP-4,4)==0x1dcb0U,"1dc92");}
