 {Bytes ram=ff_node();State s=pre(0x1dcb0,0x48,0);check(runs_to(ram,s,0x201a2)&&get(ram,NODE,4)==0x1e8deU,"1dcb0 bits 3 and 6 (the second write wins)");}
 {Bytes ram=ff_node();State s=pre(0x1dcb0,0xffffffb7,0);check(runs_to(ram,s,0x201a2)&&get(ram,NODE,4)==0xffffffffU,"1dcb0 neither");}
 {Bytes ram=base_ram("");State s=st(0x1dccc);s.carry=ms5::AnimationCarrySet;check(runs_to(ram,s,0x201a2),"1dccc");}
 // ---- 1efd6: A0 := 1b6fc; BSR.W 1cab6 (return 1efde).  1efde: (A6) := 1efe4 -> 1efe4: BSR.W 1cd98 (return 1efe8).
 {Bytes ram=base_ram("");State s=st(0x1efd6);check(runs_to(ram,s,0x1cab6)&&s.a[0]==0x1b6fcU&&get(ram,SP-4,4)==0x1efdeU,"1efd6");}
 {Bytes ram=ff_node();State s=st(0x1efde);check(runs_to(ram,s,0x1cd98)&&get(ram,NODE,4)==0x1efe4U&&get(ram,NODE+4,1)==0xffU&&get(ram,SP-4,4)==0x1efe8U,"1efde");}
