 {Bytes ram=base_ram("");put(ram,NODE+0x15,1,0x7f);State s=st(0x1efe8);check(runs_to(ram,s,0x1fae8),"1efe8 7f");}
 {Bytes ram=base_ram("");put(ram,NODE+0x15,1,0x80);put(ram,NODE+0x9e,1,1);State s=pre(0x1efe8,0x20,0);check(runs_to(ram,s,0x1fa3c),"1efe8 80 -> 1eff2 bit 5 -> 1effa 9e 1 -> 1f00c -> 1f016");}
 {Bytes ram=base_ram("");put(ram,NODE+0x15,1,0x80);State s=pre(0x1efee,0,0);check(runs_to(ram,s,0x1cec2)&&get(ram,SP-4,4)==0x1f02eU,"1efee 80 -> 1eff2 -> 1f01a -> 1f022 -> 1f02a");}
